"""产物页码裁剪（v2.3.32）。

pdf2zh 的 pages 参数语义是「只翻这些页，但输出整个文档」。用户选「仅首页」后
拿到的是 24 页的 PDF——第 1 页中文、其余 23 页还是英文原文。用户翻到后面看到
英文就以为「没翻译」，看到 24 页就以为「全部都在」。

这里在翻译结束后把产物裁成只含用户选的页，让「仅首页」真的只出首页。

页码映射：
* mono / side_by_side：每个原始页对应产物里 1 页 → 直接保留 pages。
* dual：原文、译文交替（第 0 页原文、第 1 页译文、第 2 页原文…）→ 每个原始页
  p 对应产物里的 [2p, 2p+1]。
"""

from __future__ import annotations

import logging
import os

logger = logging.getLogger(__name__)


def crop_to_pages(path: str, pages, kind: str) -> bool:
    """把产物裁剪成只含 pages 指定的页（0-indexed）。

    :param pages: 用户选的原始页码列表（0-indexed）；None 或空表示全部，不裁剪。
    :param kind: "mono" / "side_by_side" / "dual"
    :return: 是否真的做了裁剪
    """
    if not pages or not path or not os.path.exists(path):
        return False
    try:
        import fitz
        pages = sorted({int(p) for p in pages})
        doc = fitz.open(path)
        n = doc.page_count
        if kind == "dual":
            keep = []
            for p in pages:
                keep += [2 * p, 2 * p + 1]
        else:
            keep = list(pages)
        keep = [k for k in keep if 0 <= k < n]
        if not keep:
            doc.close()
            return False
        if len(keep) == n:          # 选的就是全部，无需裁剪
            doc.close()
            return False
        doc.select(keep)            # 只保留这些页并按 keep 顺序重排
        tmp = path + ".crop.pdf"
        doc.save(tmp, garbage=3, deflate=True)
        doc.close()
        os.replace(tmp, path)
        logger.info("产物裁剪 %s: %d 页 → %d 页", os.path.basename(path), n, len(keep))
        return True
    except Exception as e:                      # noqa: BLE001 — 裁剪失败不该毁掉翻译
        logger.warning("产物页码裁剪失败（保留完整产物）: %s: %s", type(e).__name__, e)
        try:
            _t = path + ".crop.pdf"
            if os.path.exists(_t):
                os.remove(_t)
        except Exception:
            pass
        return False
